mapper.select:
select r.resource_id, r.author_id, r.resource_type, r.resource_category_id,
       r.title, r.summary, r.file_object_id, r.link_url, r.link_icon,
       r.status, r.review_status, r.publish_time, r.download_count,
       r.create_by, r.create_time, r.update_by, r.update_time, r.deleted,
       u.nick_name as author_nickname,
       c.category_name as category_name,
       f.original_name as original_name, f.content_length as content_length, f.content_type as content_type
from resource r
        left join sys_user u on r.author_id = u.user_id
        left join resource_category c on r.resource_category_id = c.category_id and c.deleted = 0
        left join file_object f on r.file_object_id = f.object_id and f.deleted = 0
where r.deleted = 0
and r.title like concat('%', #{title}, '%')
and r.resource_type = #{resourceType}
and r.resource_category_id = #{resourceCategoryId}
and r.status = #{status}
and r.review_status = #{reviewStatus}
and r.create_by = #{createBy}
and r.author_id = #{authorId}
and r.create_time >= #{beginTime}
and r.create_time <= #{endTime}
order by r.publish_time desc, r.resource_id desc

mapper.update:
update resource
author_id = #{authorId}, resource_type = #{resourceType}, resource_category_id = #{resourceCategoryId}, title = #{title}, summary = #{summary}, description = #{description}, file_object_id = #{fileObjectId}, link_url = #{linkUrl}, link_icon = #{linkIcon}, status = #{status}, review_status = #{reviewStatus}, publish_time = #{publishTime}, download_count = #{downloadCount}, deleted = #{deleted}, update_by = #{updateBy}, update_time = now()
where resource_id = #{resourceId}
